package com.gsl;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("group-slot-locked")
public interface GroupSlotLockedConfig extends Config {
  @ConfigItem(
      keyName = "penaltyOverlay",
      name = "Penalty overlay",
      description =
          "Black out the screen (except inventory/equipment) when wearing an illegal loadout")
  default boolean penaltyOverlay() {
    return true;
  }

  @ConfigItem(
      keyName = "highlightRestricted",
      name = "Highlight restricted items",
      description = "Draw a red overlay on items that cannot be equipped")
  default boolean highlightRestricted() {
    return true;
  }

  @ConfigItem(
      keyName = "maxHeldTokens",
      name = "Max held tokens",
      description = "Maximum slot token items allowed in personal bank + inventory")
  default int maxHeldTokens() {
    return 5;
  }

  @ConfigItem(
      keyName = "maxEquipped",
      name = "Max equipped slots",
      description = "Maximum tracked equipment slots that may be filled at once")
  default int maxEquipped() {
    return 5;
  }

  @ConfigItem(
      keyName = "showTokenBadge",
      name = "Replace token icons",
      description = "Replace team cape sprites with slot icons in inventory, bank, and equipment")
  default boolean replaceTokenIcons() {
    return true;
  }

  @ConfigItem(
      keyName = "showEquipmentIndicators",
      name = "Equipment indicators",
      description = "Show a check/cross badge on each Worn Equipment tab slot for token status")
  default boolean showEquipmentIndicators() {
    return true;
  }

  @ConfigItem(
      keyName = "bankRefreshInterval",
      name = "Bank refresh interval",
      description = "Game ticks between bank rescans when the bank container is loaded")
  default int bankRefreshInterval() {
    return 10;
  }

  @ConfigItem(
      keyName = "chatWarnings",
      name = "Chat warnings",
      description =
          "Show chat messages when entering an illegal loadout or exceeding the token cap")
  default boolean chatWarnings() {
    return true;
  }
}

package com.gsl;

import com.google.inject.Provides;
import com.gsl.menu.SlotMenuHandler;
import com.gsl.menu.TokenBankSearchHandler;
import com.gsl.overlay.EquipmentTokenClaimOverlay;
import com.gsl.overlay.ItemRestrictionOverlay;
import com.gsl.overlay.TokenBankDragOverlay;
import com.gsl.overlay.TokenInventoryDragOverlay;
import com.gsl.overlay.TokenPressHoldOverlay;
import com.gsl.overlay.TokenItemDragOverlay;
import com.gsl.overlay.TokenTooltipOverlay;
import com.gsl.overlay.ViolationOverlay;
import com.gsl.service.SlotDisplayService;
import com.gsl.service.SlotStateService;
import com.gsl.service.TokenModelOverrideService;
import com.gsl.service.ViolationNotifier;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ScriptID;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ConfigSync;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
    name = "Group Slot Locked",
    description = "Slot token requirements and equip limits for group ironman teams",
    tags = {"ironman", "group", "equipment"})
public class GroupSlotLockedPlugin extends Plugin {
  @Inject private Client client;
  @Inject private SlotStateService slotStateService;
  @Inject private SlotDisplayService displayService;
  @Inject private TokenModelOverrideService tokenModelOverrideService;
  @Inject private ViolationNotifier violationNotifier;
  @Inject private SlotMenuHandler slotMenuHandler;
  @Inject private TokenBankSearchHandler tokenBankSearchHandler;
  @Inject private ItemRestrictionOverlay itemRestrictionOverlay;
  @Inject private TokenInventoryDragOverlay tokenInventoryDragOverlay;
  @Inject private TokenBankDragOverlay tokenBankDragOverlay;
  @Inject private TokenPressHoldOverlay tokenPressHoldOverlay;
  @Inject private TokenItemDragOverlay tokenItemDragOverlay;
  @Inject private TokenTooltipOverlay tokenTooltipOverlay;
  @Inject private ViolationOverlay violationOverlay;
  @Inject private EquipmentTokenClaimOverlay equipmentTokenClaimOverlay;
  @Inject private OverlayManager overlayManager;
  @Inject private EventBus eventBus;
  @Inject private ClientThread clientThread;
  @Inject private GroupSlotLockedConfig config;

  @Override
  protected void startUp() {
    displayService.ensureDefaultIcons();
    displayService.warmIconCache();
    overlayManager.add(itemRestrictionOverlay);
    overlayManager.add(tokenInventoryDragOverlay);
    overlayManager.add(tokenBankDragOverlay);
    overlayManager.add(tokenPressHoldOverlay);
    overlayManager.add(tokenItemDragOverlay);
    overlayManager.add(tokenTooltipOverlay);
    overlayManager.add(violationOverlay);
    overlayManager.add(equipmentTokenClaimOverlay);
    eventBus.register(slotMenuHandler);
    eventBus.register(tokenBankSearchHandler);
    eventBus.register(tokenModelOverrideService);
    slotStateService.addListener(violationNotifier::onStateChanged);
    clientThread.invoke(
        () -> {
          slotStateService.refreshAll();
          violationNotifier.onStateChanged(slotStateService.getState());
          if (config.replaceTokenIcons()) {
            tokenModelOverrideService.warmUp();
          }
        });
    log.info("Group Slot Locked started");
  }

  @Override
  protected void shutDown() {
    overlayManager.remove(itemRestrictionOverlay);
    overlayManager.remove(tokenInventoryDragOverlay);
    overlayManager.remove(tokenBankDragOverlay);
    overlayManager.remove(tokenPressHoldOverlay);
    overlayManager.remove(tokenItemDragOverlay);
    overlayManager.remove(tokenTooltipOverlay);
    overlayManager.remove(violationOverlay);
    overlayManager.remove(equipmentTokenClaimOverlay);
    eventBus.unregister(slotMenuHandler);
    eventBus.unregister(tokenBankSearchHandler);
    eventBus.unregister(tokenModelOverrideService);
    slotStateService.removeListener(violationNotifier::onStateChanged);
    violationNotifier.reset();
    clientThread.invoke(tokenModelOverrideService::restore);
    log.debug("Group Slot Locked stopped");
  }

  @Subscribe
  public void onGameTick(GameTick tick) {
    // Bank before inventory: refreshInventoryAndWorn() reuses the cached bank snapshot rather
    // than rescanning, so refresh that cache first on ticks where it's due.
    int interval = Math.max(1, config.bankRefreshInterval());
    if (client.getTickCount() % interval == 0) {
      slotStateService.refreshBankIfAvailable();
    }
    slotStateService.refreshInventoryAndWorn();
    slotStateService.refreshGroupStorage();
  }

  @Subscribe
  public void onItemContainerChanged(ItemContainerChanged event) {
    int id = event.getContainerId();
    if (id == InventoryID.INV
        || id == InventoryID.BANK
        || id == InventoryID.WORN
        || id == InventoryID.INV_GROUP_TEMP) {
      if (id == InventoryID.INV_GROUP_TEMP) {
        slotStateService.refreshGroupStorage();
      } else {
        slotStateService.refreshAll();
      }
    }
  }

  @Subscribe
  public void onScriptPostFired(ScriptPostFired event) {
    if (event.getScriptId() == ScriptID.BANKMAIN_FINISHBUILDING
        || event.getScriptId() == ScriptID.GROUP_IRONMAN_STORAGE_BUILD) {
      slotStateService.refreshAll();
    }
  }

  @Subscribe
  public void onConfigChanged(ConfigChanged event) {
    if (!"group-slot-locked".equals(event.getGroup()) || !"showTokenBadge".equals(event.getKey())) {
      return;
    }
    clientThread.invoke(
        () -> {
          if (config.replaceTokenIcons()) {
            tokenModelOverrideService.warmUp();
          } else {
            tokenModelOverrideService.restore();
          }
        });
  }

  @Subscribe
  public void onConfigSync(ConfigSync event) {
    if (client.getGameState() != GameState.LOGGED_IN) {
      return;
    }
    slotStateService.reloadSnapshots();
    slotStateService.refreshAll();
    violationNotifier.onStateChanged(slotStateService.getState());
  }

  @Subscribe
  public void onRuneScapeProfileChanged(RuneScapeProfileChanged event) {
    slotStateService.reloadSnapshots();
    slotStateService.refreshAll();
    violationNotifier.onStateChanged(slotStateService.getState());
  }

  @Subscribe
  public void onGameStateChanged(GameStateChanged event) {
    if (event.getGameState() == GameState.LOGIN_SCREEN
        || event.getGameState() == GameState.CONNECTION_LOST) {
      slotStateService.onLogout();
      return;
    }
    if (event.getGameState() == GameState.LOGGED_IN) {
      clientThread.invokeLater(
          () -> {
            slotStateService.onLogin();
            slotStateService.refreshAll();
            violationNotifier.reset();
            violationNotifier.onStateChanged(slotStateService.getState());
          });
    }
  }

  @Provides
  GroupSlotLockedConfig provideConfig(ConfigManager configManager) {
    return configManager.getConfig(GroupSlotLockedConfig.class);
  }
}

package com.gsl.menu;

import com.gsl.model.SlotType;
import com.gsl.service.SlotDisplayService;
import com.gsl.util.BankItemUtils;
import com.gsl.util.TokenItemWidgetScopes;
import java.util.Locale;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.ChatLineBuffer;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.MessageNode;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.util.ColorUtil;

public class SlotMenuHandler {
  private static final Set<String> EQUIP_OPTIONS = Set.of("wear", "wield", "equip");
  private static final int[] TRADE_CONFIRM_OFFER_WIDGETS = {
    InterfaceID.Tradeconfirm.YOUR_OFFER, InterfaceID.Tradeconfirm.OTHER_OFFER,
  };
  private int pendingSuppressTokenExamineItemId = -1;
  private int pendingSuppressTokenExamineUntilTick = -1;
  private final Client client;
  private final SlotDisplayService displayService;
  private final ChatMessageManager chatMessageManager;
  private final ItemManager itemManager;

  @Inject
  SlotMenuHandler(
      Client client,
      SlotDisplayService displayService,
      ChatMessageManager chatMessageManager,
      ItemManager itemManager) {
    this.client = client;
    this.displayService = displayService;
    this.chatMessageManager = chatMessageManager;
    this.itemManager = itemManager;
  }

  @Subscribe
  public void onMenuEntryAdded(MenuEntryAdded event) {
    MenuEntry entry = event.getMenuEntry();
    if (!TokenItemWidgetScopes.isTokenItemMenuContext(entry)) {
      return;
    }
    int itemId = resolveItemId(entry, event.getItemId());
    if (itemId <= 0) {
      return;
    }
    if (resolveTokenSlot(itemId) != null) {
      handleTokenEntry(entry, itemId);
    }
  }

  @Subscribe
  public void onMenuOpened(MenuOpened event) {
    MenuEntry[] entries = event.getMenuEntries();
    boolean changed = false;
    for (int i = 0; i < entries.length; i++) {
      MenuEntry entry = entries[i];
      int itemId = resolveItemId(entry);
      if (itemId <= 0) {
        continue;
      }
      SlotType slot = resolveTokenSlot(itemId);
      if (slot != null && handleTokenMenuOpenedEntry(entry, entries, i, slot)) {
        changed = true;
      }
    }
    if (changed) {
      event.setMenuEntries(entries);
    }
  }

  @Subscribe(priority = Short.MIN_VALUE)
  public void onBeforeRender(BeforeRender event) {
    if (client.isMenuOpen()) {
      return;
    }
    MenuEntry[] entries = client.getMenu().getMenuEntries();
    if (entries.length == 0) {
      return;
    }
    if (applyTopHoverLabel(entries[entries.length - 1])) {
      client.getMenu().setMenuEntries(entries);
    }
  }

  @Subscribe(priority = Short.MIN_VALUE)
  public void onPostMenuSort(PostMenuSort event) {
    MenuEntry[] entries = client.getMenu().getMenuEntries();
    if (applyTokenMenuChanges(entries)) {
      client.getMenu().setMenuEntries(entries);
    }
  }

  @Subscribe
  public void onMenuOptionClicked(MenuOptionClicked event) {
    MenuEntry entry = event.getMenuEntry();
    int itemId = resolveItemId(entry);
    if (itemId <= 0) {
      return;
    }
    SlotType slot = resolveTokenSlot(itemId);
    if (slot != null && isExamineEntry(entry)) {
      pendingSuppressTokenExamineItemId = itemId;
      pendingSuppressTokenExamineUntilTick = client.getTickCount() + 5;
      chatMessageManager.queue(
          QueuedMessage.builder()
              .type(ChatMessageType.GAMEMESSAGE)
              .runeLiteFormattedMessage(displayService.getTokenExamineChatMessage(slot))
              .build());
    }
  }

  @Subscribe
  public void onClientTick(ClientTick event) {
    if (pendingSuppressTokenExamineItemId > 0
        && client.getTickCount() > pendingSuppressTokenExamineUntilTick) {
      clearPendingTokenExamineSuppression();
    }

    relabelTradeConfirmText();

    if (client.isMenuOpen()) {
      return;
    }
    MenuEntry[] entries = client.getMenu().getMenuEntries();
    if (entries.length == 0) {
      return;
    }
    if (applyTopHoverLabel(entries[entries.length - 1])) {
      client.getMenu().setMenuEntries(entries);
    }
  }

  /**
   * The second trade confirmation screen ("You will give" / "You will receive") lists items as
   * plain text on the dynamic children of {@code Tradeconfirm.YOUR_OFFER}/{@code OTHER_OFFER}
   * (one child per offered item line), not as item-slot widgets — none of the menu/overlay hooks
   * above apply to it. Rewrite the real cape name to the slot label directly in that text.
   */
  private void relabelTradeConfirmText() {
    for (int componentId : TRADE_CONFIRM_OFFER_WIDGETS) {
      Widget container = client.getWidget(componentId);
      if (container == null) {
        continue;
      }
      Widget[] children = container.getDynamicChildren();
      if (children == null) {
        continue;
      }
      for (Widget child : children) {
        relabelWidgetText(child);
      }
    }
  }

  private void relabelWidgetText(@Nullable Widget widget) {
    if (widget == null) {
      return;
    }
    String text = widget.getText();
    if (text == null || text.isEmpty()) {
      return;
    }
    String relabeled = relabelTokenNames(text);
    if (!relabeled.equals(text)) {
      widget.setText(relabeled);
    }
  }

  private String relabelTokenNames(String text) {
    String result = text;
    for (SlotType slot : SlotType.values()) {
      String realName = itemManager.getItemComposition(slot.getTokenItemId()).getName();
      if (realName == null || realName.isEmpty() || !result.contains(realName)) {
        continue;
      }
      result =
          result.replace(
              realName,
              ColorUtil.wrapWithColorTag(
                  displayService.getHoverTargetText(slot, 1), JagexColors.MENU_TARGET));
    }
    return result;
  }

  @Subscribe(priority = Short.MAX_VALUE)
  public void onScriptCallbackEvent(ScriptCallbackEvent event) {
    if (!isSuppressingTokenExamine()) {
      return;
    }
    if (!"chatFilterCheck".equals(event.getEventName())) {
      return;
    }

    int[] intStack = client.getIntStack();
    int intStackSize = client.getIntStackSize();
    if (intStack[intStackSize - 2] != ChatMessageType.ITEM_EXAMINE.getType()) {
      return;
    }

    intStack[intStackSize - 3] = 0;
  }

  @Subscribe(priority = -2)
  public void onChatMessage(ChatMessage event) {
    if (!isSuppressingTokenExamine()) {
      return;
    }
    if (event.getType() != ChatMessageType.ITEM_EXAMINE) {
      return;
    }

    MessageNode messageNode = event.getMessageNode();
    ChatLineBuffer chatLineBuffer =
        client.getChatLineMap().get(ChatMessageType.ITEM_EXAMINE.getType());
    if (chatLineBuffer != null) {
      chatLineBuffer.removeMessageNode(messageNode);
    }
  }

  private boolean isSuppressingTokenExamine() {
    return pendingSuppressTokenExamineItemId > 0
        && client.getTickCount() <= pendingSuppressTokenExamineUntilTick;
  }

  private void clearPendingTokenExamineSuppression() {
    pendingSuppressTokenExamineItemId = -1;
    pendingSuppressTokenExamineUntilTick = -1;
  }

  private void handleTokenEntry(MenuEntry entry, int itemId) {
    SlotType slot = resolveTokenSlot(itemId);
    if (slot == null) {
      return;
    }
    if (isEquipOption(entry.getOption())) {
      // Token items are reskinned capes with no legitimate use equipped; drop the option
      // entirely rather than just deprioritizing it so it can't be clicked by accident.
      client.getMenu().removeMenuEntry(entry);
      return;
    }
    applyTokenHoverTarget(entry, slot);
    if (!TokenItemWidgetScopes.isTokenLeftClickReorderContext(entry)) {
      return;
    }
    if (shouldDeprioritizeTokenOption(entry.getOption())) {
      entry.setDeprioritized(true);
    }
  }

  private boolean handleTokenMenuOpenedEntry(
      MenuEntry entry, MenuEntry[] entries, int index, SlotType slot) {
    boolean changed = applyTokenHoverTarget(entry, slot);
    if (!TokenItemWidgetScopes.isTokenLeftClickReorderContext(entry)) {
      return changed;
    }
    if (shouldDeprioritizeTokenOption(entry.getOption())) {
      entry.setDeprioritized(true);
      changed = true;
    }
    if (isExamineEntry(entry)) {
      applyTokenSlotMenuText(entry, slot);
      promoteEntry(entries, index);
      changed = true;
    }
    return changed;
  }

  private boolean applyTokenMenuChanges(MenuEntry[] entries) {
    int preferredIndex = -1;
    boolean changed = false;
    boolean reorderContext = false;

    for (int i = 0; i < entries.length; i++) {
      MenuEntry entry = entries[i];
      if (!TokenItemWidgetScopes.isTokenItemMenuContext(entry)) {
        continue;
      }
      if (resolveTokenSlot(resolveItemId(entry)) == null) {
        continue;
      }
      if (!TokenItemWidgetScopes.isTokenLeftClickReorderContext(entry)) {
        continue;
      }
      reorderContext = true;
      if (shouldDeprioritizeTokenOption(entry.getOption())) {
        entry.setDeprioritized(true);
        changed = true;
      }
      if (isExamineEntry(entry)) {
        preferredIndex = i;
      }
    }

    if (reorderContext && preferredIndex >= 0) {
      if (preferredIndex < entries.length - 1) {
        promoteEntry(entries, preferredIndex);
      }
      prepareExamineForLeftClick(entries[entries.length - 1]);
      changed = true;
    }

    if (applyTopHoverLabel(entries[entries.length - 1])) {
      changed = true;
    }

    return changed;
  }

  /** Updates the top menu row used for the hover bar. Returns true if option/target changed. */
  private boolean applyTopHoverLabel(MenuEntry top) {
    if (!TokenItemWidgetScopes.isTokenItemMenuContext(top)) {
      return false;
    }
    SlotType slot = resolveTokenSlot(resolveItemId(top));
    if (slot == null) {
      return false;
    }

    String option = top.getOption();
    String target = getColoredSlotTarget(top, slot);
    if (isExamineEntry(top)) {
      option = getExamineVerb(top);
    }

    if (option.equals(top.getOption()) && target.equals(top.getTarget())) {
      return false;
    }

    top.setOption(option);
    top.setTarget(target);
    return true;
  }

  private static void promoteEntry(MenuEntry[] entries, int index) {
    if (index < 0 || index >= entries.length - 1) {
      return;
    }
    MenuEntry promoted = entries[index];
    System.arraycopy(entries, index + 1, entries, index, entries.length - index - 1);
    entries[entries.length - 1] = promoted;
  }

  /**
   * Examine is added as {@link MenuAction#CC_OP_LOW_PRIORITY}, which is right-click only even when
   * promoted to the top of the menu. Upgrade it so left-click executes instead of opening the menu.
   */
  private static void prepareExamineForLeftClick(MenuEntry entry) {
    if (entry == null || !isExamineEntry(entry)) {
      return;
    }
    if (entry.getType() == MenuAction.CC_OP_LOW_PRIORITY) {
      entry.setType(MenuAction.CC_OP);
    }
    entry.setForceLeftClick(true);
  }

  private static boolean shouldDeprioritizeTokenOption(String option) {
    if (option == null) {
      return false;
    }
    // Wear/Wield/Equip on token items are removed entirely in onMenuEntryAdded, not just
    // deprioritized, so they aren't handled here.
    return option.equalsIgnoreCase("use") || option.equalsIgnoreCase("drop");
  }

  private void applyTokenSlotMenuText(MenuEntry entry, SlotType slot) {
    applyTokenExamineMenuText(entry, slot);
  }

  private void applyTokenExamineMenuText(MenuEntry entry, SlotType slot) {
    entry.setOption(getExamineVerb(entry));
    entry.setTarget(getColoredSlotTarget(entry, slot));
  }

  private String getColoredSlotTarget(MenuEntry entry, SlotType slot) {
    return ColorUtil.wrapWithColorTag(
        displayService.getHoverTargetText(slot, resolveEntryQuantity(entry)),
        JagexColors.MENU_TARGET);
  }

  private int resolveEntryQuantity(MenuEntry entry) {
    Widget widget = resolveItemWidget(entry);
    if (widget == null) {
      return 1;
    }
    return BankItemUtils.resolvePlaceholderDisplayQuantity(
        itemManager, widget.getItemId(), widget.getItemQuantity());
  }

  private boolean applyTokenHoverTarget(MenuEntry entry, SlotType slot) {
    if (TokenItemWidgetScopes.isTokenBankActionContext(entry)) {
      if (isExamineEntry(entry)) {
        applyTokenExamineMenuText(entry, slot);
        return true;
      }
      // Keep Withdraw-1 / Deposit-1; replace cape name with orange slot label.
      entry.setTarget(getColoredSlotTarget(entry, slot));
      return true;
    }

    if (TokenItemWidgetScopes.isTokenLeftClickReorderContext(entry)) {
      if (isExamineEntry(entry)) {
        applyTokenExamineMenuText(entry, slot);
        return true;
      }
      entry.setTarget(getColoredSlotTarget(entry, slot));
      return true;
    }

    if (isExamineEntry(entry)) {
      applyTokenExamineMenuText(entry, slot);
      return true;
    }

    entry.setTarget(getColoredSlotTarget(entry, slot));
    return true;
  }

  private SlotType resolveTokenSlot(int itemId) {
    return BankItemUtils.resolveSlotType(itemManager, itemId);
  }

  private int resolveItemId(MenuEntry entry) {
    return resolveItemId(entry, entry.getItemId());
  }

  private int resolveItemId(MenuEntry entry, int fallbackItemId) {
    if (fallbackItemId > 0) {
      return fallbackItemId;
    }
    int itemId = entry.getItemId();
    if (itemId > 0) {
      return itemId;
    }
    Widget widget = entry.getWidget();
    if (widget != null) {
      itemId = resolveItemIdFromWidget(widget);
      if (itemId > 0) {
        return itemId;
      }
    }
    itemId = resolveItemIdFromContainer(entry);
    if (itemId > 0) {
      return itemId;
    }
    widget = resolveItemWidget(entry);
    if (widget != null) {
      itemId = widget.getItemId();
      if (itemId > 0) {
        return itemId;
      }
    }
    int widgetId = entry.getParam1();
    int childIndex = entry.getParam0();
    if (widgetId <= 0) {
      return -1;
    }
    Widget container = client.getWidget(widgetId);
    if (container == null) {
      return -1;
    }
    Widget child = container.getChild(childIndex);
    return child != null ? child.getItemId() : -1;
  }

  @Nullable
  private Widget resolveItemWidget(MenuEntry entry) {
    Widget widget = entry.getWidget();
    if (widget != null && widget.getItemId() > 0) {
      return widget;
    }
    int componentId = entry.getParam1();
    int slot = entry.getParam0();
    if (componentId <= 0 || slot < 0) {
      return widget;
    }
    Widget container = client.getWidget(componentId);
    if (container == null) {
      return widget;
    }
    Widget[] dynamic = container.getDynamicChildren();
    if (dynamic != null && slot < dynamic.length) {
      Widget dynamicChild = dynamic[slot];
      if (dynamicChild != null) {
        return dynamicChild;
      }
    }
    Widget child = container.getChild(slot);
    return child != null ? child : widget;
  }

  private ItemContainer containerForComponent(int componentId) {
    if (componentId == InterfaceID.Inventory.ITEMS
        || componentId == InterfaceID.Bankside.ITEMS
        || componentId == InterfaceID.SharedBankSide.ITEMS) {
      return client.getItemContainer(InventoryID.INV);
    }
    if (componentId == InterfaceID.Bankmain.ITEMS
        || componentId == InterfaceID.Bankmain.BANKTAGS_DISPLAY_ITEMS) {
      return client.getItemContainer(InventoryID.BANK);
    }
    if (componentId == InterfaceID.SharedBank.ITEMS
        || componentId == InterfaceID.SharedBank.MAIN_BANK) {
      return client.getItemContainer(InventoryID.INV_GROUP_TEMP);
    }
    return null;
  }

  private int resolveItemIdFromContainer(MenuEntry entry) {
    int componentId = entry.getParam1();
    int slot = entry.getParam0();
    if (componentId <= 0 || slot < 0) {
      return -1;
    }
    ItemContainer container = containerForComponent(componentId);
    if (container == null) {
      return -1;
    }
    Item item = container.getItem(slot);
    return item != null ? item.getId() : -1;
  }

  private static int resolveItemIdFromWidget(Widget widget) {
    int group = WidgetUtil.componentToInterface(widget.getId());
    if (group == InterfaceID.WORNITEMS
        || (group == InterfaceID.BANKMAIN
            && widget.getParentId() == InterfaceID.Bankside.WORNOPS)) {
      Widget itemWidget = widget.getChild(1);
      return itemWidget != null ? itemWidget.getItemId() : -1;
    }

    if (widget.getId() == InterfaceID.Inventory.ITEMS
        || group == InterfaceID.EQUIPMENT_SIDE
        || widget.getId() == InterfaceID.Bankmain.ITEMS
        || group == InterfaceID.BANKSIDE
        || widget.getId() == InterfaceID.SharedBank.ITEMS
        || group == InterfaceID.SHARED_BANK_SIDE) {
      return widget.getItemId();
    }

    return widget.getItemId();
  }

  private static boolean isExamineEntry(MenuEntry entry) {
    if (entry == null) {
      return false;
    }
    if (entry.getIdentifier() == 10) {
      return true;
    }
    return isExamineOption(entry.getOption());
  }

  private static boolean isEquipOption(String option) {
    return option != null && EQUIP_OPTIONS.contains(option.toLowerCase(Locale.ENGLISH));
  }

  private static String getExamineVerb(MenuEntry entry) {
    String option = entry.getOption();
    if (option != null && option.toLowerCase(Locale.ENGLISH).startsWith("inspect")) {
      return "Inspect";
    }
    return "Examine";
  }

  private static boolean isExamineOption(String option) {
    if (option == null) {
      return false;
    }
    String lower = option.toLowerCase(Locale.ENGLISH);
    return lower.startsWith("examine") || lower.startsWith("inspect");
  }
}

package com.gsl.menu;

import com.gsl.model.SlotType;
import com.gsl.service.SlotDisplayService;
import com.gsl.util.BankItemUtils;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

/**
 * Extends RuneLite bank search so slot tokens and their placeholders match custom slot names
 * (e.g. searching {@code ammo} finds the Ammo slot token instead of only matching cape names).
 */
public class TokenBankSearchHandler {
  private static final String NUMBER_REGEX = "[0-9]+(\\.[0-9]+)?[kmb]?";
  private static final Pattern VALUE_SEARCH_PATTERN =
      Pattern.compile(
          "^(?<mode>qty|ge|ha|alch)?"
              + " *(?<individual>i|iv|individual|per)?"
              + " *(((?<op>[<>=]|>=|<=) *(?<num>"
              + NUMBER_REGEX
              + "))|"
              + "((?<num1>"
              + NUMBER_REGEX
              + ") *- *(?<num2>"
              + NUMBER_REGEX
              + ")))$",
          Pattern.CASE_INSENSITIVE);

  private final Client client;
  private final SlotDisplayService displayService;
  private final ItemManager itemManager;

  @Inject
  TokenBankSearchHandler(Client client, SlotDisplayService displayService, ItemManager itemManager) {
    this.client = client;
    this.displayService = displayService;
    this.itemManager = itemManager;
  }

  @Subscribe(priority = 0)
  public void onScriptCallbackEvent(ScriptCallbackEvent event) {
    if (!"bankSearchFilter".equals(event.getEventName())) {
      return;
    }

    int[] intStack = client.getIntStack();
    Object[] objectStack = client.getObjectStack();
    int intStackSize = client.getIntStackSize();
    int objectStackSize = client.getObjectStackSize();

    int itemId = intStack[intStackSize - 1];
    if (itemId <= 0) {
      return;
    }

    String search = (String) objectStack[objectStackSize - 1];
    if (search == null || search.isEmpty() || isDelegatedBankSearch(search)) {
      return;
    }

    SlotType slot = BankItemUtils.resolveSlotType(itemManager, itemId);
    if (slot == null) {
      return;
    }

    if (displayService.matchesBankSearch(slot, search)) {
      intStack[intStackSize - 2] = 1;
    }
  }

  private static boolean isDelegatedBankSearch(String search) {
    String trimmed = search.trim();
    if (trimmed.regionMatches(true, 0, "tag:", 0, 4)) {
      return true;
    }
    return VALUE_SEARCH_PATTERN.matcher(trimmed).matches();
  }
}

package com.gsl.model;

import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import lombok.Value;

@Value
public class LocalSlotState {
  Set<SlotType> tokensPresent;
  Set<SlotType> tokensInGroupStorage;
  Set<SlotType> equippedSlots;
  Map<SlotType, Integer> equippedItemIds;
  int heldTokenCount;

  public static LocalSlotState empty() {
    return new LocalSlotState(
        Collections.emptySet(),
        Collections.emptySet(),
        Collections.emptySet(),
        Collections.emptyMap(),
        0);
  }

  public boolean hasToken(SlotType slot) {
    return tokensPresent.contains(slot);
  }

  public boolean hasTokenInGroupStorage(SlotType slot) {
    return tokensInGroupStorage.contains(slot);
  }

  public boolean isEquipped(SlotType slot) {
    return equippedSlots.contains(slot);
  }

  public int getEquippedItemId(SlotType slot) {
    return equippedItemIds.getOrDefault(slot, -1);
  }

  public Set<SlotType> getTokensPresent() {
    return Collections.unmodifiableSet(tokensPresent);
  }

  public Set<SlotType> getTokensInGroupStorage() {
    return Collections.unmodifiableSet(tokensInGroupStorage);
  }

  public Set<SlotType> getEquippedSlots() {
    return Collections.unmodifiableSet(equippedSlots);
  }

  public Map<SlotType, Integer> getEquippedItemIds() {
    return Collections.unmodifiableMap(equippedItemIds);
  }

  public static LocalSlotState of(
      Set<SlotType> tokensPresent,
      Set<SlotType> tokensInGroupStorage,
      Set<SlotType> equippedSlots,
      Map<SlotType, Integer> equippedItemIds,
      int heldTokenCount) {
    return new LocalSlotState(
        copySlotSet(tokensPresent),
        copySlotSet(tokensInGroupStorage),
        copySlotSet(equippedSlots),
        equippedItemIds == null || equippedItemIds.isEmpty()
            ? Collections.emptyMap()
            : new EnumMap<>(equippedItemIds),
        heldTokenCount);
  }

  public static LocalSlotState of(
      Set<SlotType> tokensPresent, Set<SlotType> equippedSlots, int heldTokenCount) {
    return of(
        tokensPresent,
        Collections.emptySet(),
        equippedSlots,
        Collections.emptyMap(),
        heldTokenCount);
  }

  private static EnumSet<SlotType> copySlotSet(Set<SlotType> slots) {
    if (slots == null || slots.isEmpty()) {
      return EnumSet.noneOf(SlotType.class);
    }
    return EnumSet.copyOf(slots);
  }
}

