import net.runelite.client.RuneLite;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;

@Slf4j
@Singleton
public class SlotStateService {
  private static final String CONFIG_GROUP = "group-slot-locked";
  private static final String KEY_BANK_TOKEN_SLOTS = "snapshotBankSlots";
  private static final String KEY_INVENTORY_TOKEN_SLOTS = "snapshotInventorySlots";

  private static final Path DATA_DIR = RuneLite.RUNELITE_DIR.toPath().resolve("group-slot-locked");
  private static final Path LOCAL_SNAPSHOT_FILE = DATA_DIR.resolve("held-tokens.properties");
  private static final Path SNAPSHOT_FILE = DATA_DIR.resolve("held-tokens.json");
  private static final Path LEGACY_BANK_SNAPSHOT_FILE = DATA_DIR.resolve("bank-tokens.json");

  private final Client client;
  private final ItemManager itemManager;
  private final SlotValidator slotValidator;
  private final ConfigManager configManager;
  private final Gson gson;
  @Getter private volatile LocalSlotState state = LocalSlotState.empty();
  private EnumSet<SlotType> lastKnownBankTokens = EnumSet.noneOf(SlotType.class);
  private int lastKnownBankTokenCount = 0;
  private EnumSet<SlotType> lastKnownInventoryTokens = EnumSet.noneOf(SlotType.class);
  private int lastKnownInventoryTokenCount = 0;
  private final List<Consumer<LocalSlotState>> listeners = new ArrayList<>();

  @Inject
  SlotStateService(
      Client client,
      ItemManager itemManager,
      SlotValidator slotValidator,
      ConfigManager configManager,
      Gson gson) {
    this.client = client;
    this.itemManager = itemManager;
    this.slotValidator = slotValidator;
    this.configManager = configManager;
    this.gson = gson;
    loadLocalSnapshotFile();
  }

  public void addListener(Consumer<LocalSlotState> listener) {
    listeners.add(listener);
  }

  public void removeListener(Consumer<LocalSlotState> listener) {
    listeners.remove(listener);
  }

  public void onLogin() {
    reloadSnapshots();
  }

  public void onLogout() {
    persistSnapshots();
  }

  /** Reload token slot snapshots from local file, then RS profile config when available. */
  public void reloadSnapshots() {
    loadLocalSnapshotFile();
    loadFromRsProfile();
    if (lastKnownBankTokens.isEmpty() && lastKnownInventoryTokens.isEmpty()) {
      migrateLegacySnapshotFiles();
    }
  }

  public void refreshAll() {
    // Bank first: refreshInventoryAndWorn() reuses the cached bank snapshot rather than
    // rescanning (see below), so refresh that cache before consuming it — otherwise moving a
    // token between bank and inventory can transiently double- or under-count it and trip a
    // bogus token-cap warning until the next refresh corrects it.
    refreshBankIfAvailable();
    refreshInventoryAndWorn();
    refreshGroupStorage();
  }

  public void refreshInventoryAndWorn() {
    EnumSet<SlotType> tokensPresent = EnumSet.noneOf(SlotType.class);
    int heldTokenCount = 0;
    TokenTotals inventoryTotals =
        resolveInventoryTokens(client.getItemContainer(InventoryID.INV));
    heldTokenCount += inventoryTotals.count;
    tokensPresent.addAll(inventoryTotals.slots);
    // Bank is scanned separately on a throttled interval (see refreshBankIfAvailable); reuse the
    // last known snapshot here instead of rescanning the whole bank every tick.
    TokenTotals bankTotals = lastKnownBankTotals();
    heldTokenCount += bankTotals.count;
    tokensPresent.addAll(bankTotals.slots);
    EnumSet<SlotType> equippedSlots = EnumSet.noneOf(SlotType.class);
    EnumMap<SlotType, Integer> equippedItemIds = new EnumMap<>(SlotType.class);
    ItemContainer worn = client.getItemContainer(InventoryID.WORN);
    if (worn != null) {
      for (SlotType slot : SlotType.values()) {
        Item item = worn.getItem(slot.getEquipmentSlot().getSlotIdx());
        if (item == null || item.getId() <= 0) {
          continue;
        }
        int canonicalId = itemManager.canonicalize(item.getId());
        equippedSlots.add(slot);
        equippedItemIds.put(slot, canonicalId);
        if (slot == SlotType.MAIN_HAND
            && slotValidator.slotsForItem(canonicalId).contains(SlotType.OFF_HAND)) {
          // Two-handed weapons block the shield slot without occupying it, so WORN never
          // reports an item there. Treat off-hand as in-use so claim/equip-count checks
          // still catch it.
          equippedSlots.add(SlotType.OFF_HAND);
          equippedItemIds.putIfAbsent(SlotType.OFF_HAND, canonicalId);
        }
      }
    }
    updateState(
        LocalSlotState.of(
            tokensPresent,
            state.getTokensInGroupStorage(),
            equippedSlots,
            equippedItemIds,
            heldTokenCount));
  }

  public void refreshBankIfAvailable() {
    ItemContainer bank = client.getItemContainer(InventoryID.BANK);
    if (bank == null) {
      return;
    }
    EnumSet<SlotType> tokensPresent = EnumSet.noneOf(SlotType.class);
    int heldTokenCount = 0;
    TokenTotals inventoryTotals =
        resolveInventoryTokens(client.getItemContainer(InventoryID.INV));
    heldTokenCount += inventoryTotals.count;
    tokensPresent.addAll(inventoryTotals.slots);
    TokenTotals bankTotals = resolveBankTokens(bank);
    heldTokenCount += bankTotals.count;
    tokensPresent.addAll(bankTotals.slots);
    updateState(
        LocalSlotState.of(
            tokensPresent,
            state.getTokensInGroupStorage(),
            state.getEquippedSlots(),
            state.getEquippedItemIds(),
            heldTokenCount));
  }

  public void refreshGroupStorage() {
    EnumSet<SlotType> groupStorageTokens = EnumSet.noneOf(SlotType.class);
    collectTokenTypes(client.getItemContainer(InventoryID.INV_GROUP_TEMP), groupStorageTokens);
    if (groupStorageTokens.equals(state.getTokensInGroupStorage())) {
      return;
    }
    updateState(
        LocalSlotState.of(
            state.getTokensPresent(),
            groupStorageTokens,
            state.getEquippedSlots(),
            state.getEquippedItemIds(),
            state.getHeldTokenCount()));
  }

  private TokenTotals resolveInventoryTokens(ItemContainer inventory) {
    if (inventory == null) {
      return TokenTotals.from(lastKnownInventoryTokens, lastKnownInventoryTokenCount);
    }
    EnumSet<SlotType> scanned = EnumSet.noneOf(SlotType.class);
    int scannedCount = collectTokens(inventory, scanned);
    if (shouldUpdateInventorySnapshot(scanned)) {
      captureInventorySnapshot(scanned, scannedCount);
      return TokenTotals.from(scanned, scannedCount);
    }
    return TokenTotals.from(lastKnownInventoryTokens, lastKnownInventoryTokenCount);
  }

  private TokenTotals resolveBankTokens(ItemContainer bank) {
    if (bank == null) {
      return lastKnownBankTotals();
    }
    EnumSet<SlotType> scanned = EnumSet.noneOf(SlotType.class);
    int scannedCount = collectTokens(bank, scanned);
    if (shouldUpdateBankSnapshot(scanned)) {
      captureBankSnapshot(scanned, scannedCount);
      return TokenTotals.from(scanned, scannedCount);
    }
    return lastKnownBankTotals();
  }

  private TokenTotals lastKnownBankTotals() {
    return TokenTotals.from(lastKnownBankTokens, lastKnownBankTokenCount);
  }

  private boolean shouldUpdateInventorySnapshot(EnumSet<SlotType> scannedTokens) {
    return !scannedTokens.isEmpty() || isInventorySnapshotReliable();
  }

  private boolean shouldUpdateBankSnapshot(EnumSet<SlotType> scannedTokens) {
    return !scannedTokens.isEmpty() || isBankInterfaceOpen();
  }

  private boolean isInventorySnapshotReliable() {
    return client.getGameState() == GameState.LOGGED_IN && client.getLocalPlayer() != null;
  }

  private void captureInventorySnapshot(EnumSet<SlotType> inventoryTokens, int inventoryCount) {
    if (inventoryTokens.equals(lastKnownInventoryTokens)
        && inventoryCount == lastKnownInventoryTokenCount) {
      return;
    }
    lastKnownInventoryTokens = EnumSet.copyOf(inventoryTokens);
    lastKnownInventoryTokenCount = inventoryCount;
    persistSnapshots();
  }

  private void captureBankSnapshot(EnumSet<SlotType> bankTokens, int bankCount) {
    if (bankTokens.equals(lastKnownBankTokens) && bankCount == lastKnownBankTokenCount) {
      return;
    }
    lastKnownBankTokens = EnumSet.copyOf(bankTokens);
    lastKnownBankTokenCount = bankCount;
    persistSnapshots();
  }

  private void persistSnapshots() {
    saveBankSlotsToProfile();
    saveInventorySlotsToProfile();
    saveLocalSnapshotFile();
  }

  private boolean isBankInterfaceOpen() {
    Widget bankItems = client.getWidget(InterfaceID.Bankmain.ITEMS);
    return bankItems != null && !bankItems.isHidden();
  }

  private void loadFromRsProfile() {
    String bankRaw = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_BANK_TOKEN_SLOTS);
    String inventoryRaw =
        configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_INVENTORY_TOKEN_SLOTS);
    if (bankRaw != null) {
      applyBankTokens(deserializeSlots(bankRaw));
    }
    if (inventoryRaw != null) {
      applyInventoryTokens(deserializeSlots(inventoryRaw));
    }
  }

  private void applyBankTokens(EnumSet<SlotType> slots) {
    lastKnownBankTokens = EnumSet.copyOf(slots);
    lastKnownBankTokenCount = estimateTokenCount(slots);
  }

  private void applyInventoryTokens(EnumSet<SlotType> slots) {
    lastKnownInventoryTokens = EnumSet.copyOf(slots);
    lastKnownInventoryTokenCount = estimateTokenCount(slots);
  }

  private static int estimateTokenCount(EnumSet<SlotType> slots) {
    return slots.size();
  }

  private void saveBankSlotsToProfile() {
    persistSlotsToProfile(KEY_BANK_TOKEN_SLOTS, lastKnownBankTokens);
  }

  private void saveInventorySlotsToProfile() {
    persistSlotsToProfile(KEY_INVENTORY_TOKEN_SLOTS, lastKnownInventoryTokens);
  }

  private void persistSlotsToProfile(String key, EnumSet<SlotType> slots) {
    String serialized = serializeSlots(slots);
    if (serialized.isEmpty()) {
      configManager.unsetRSProfileConfiguration(CONFIG_GROUP, key);
    } else {
      configManager.setRSProfileConfiguration(CONFIG_GROUP, key, serialized);
    }
  }

  private void saveLocalSnapshotFile() {
    try {
      Files.createDirectories(DATA_DIR);
      Properties properties = new Properties();
      properties.setProperty("bank", serializeSlots(lastKnownBankTokens));
      properties.setProperty("inventory", serializeSlots(lastKnownInventoryTokens));
      try (Writer writer = Files.newBufferedWriter(LOCAL_SNAPSHOT_FILE)) {
        properties.store(writer, "Group Slot Locked held token slots");
      }
    } catch (IOException ex) {
      log.debug("Failed to save local token snapshot to {}", LOCAL_SNAPSHOT_FILE, ex);
    }
  }

  private void loadLocalSnapshotFile() {
    if (!Files.isRegularFile(LOCAL_SNAPSHOT_FILE)) {
      return;
    }
    try (Reader reader = Files.newBufferedReader(LOCAL_SNAPSHOT_FILE)) {
      Properties properties = new Properties();
      properties.load(reader);
      applyBankTokens(deserializeSlots(properties.getProperty("bank", "")));
      applyInventoryTokens(deserializeSlots(properties.getProperty("inventory", "")));
    } catch (IOException | RuntimeException ex) {
      log.debug("Failed to load local token snapshot from {}", LOCAL_SNAPSHOT_FILE, ex);
    }
  }

  private static String serializeSlots(EnumSet<SlotType> slots) {
    if (slots.isEmpty()) {
      return "";
    }
    return slots.stream().map(Enum::name).sorted().collect(Collectors.joining(","));
  }

  private static EnumSet<SlotType> deserializeSlots(String serialized) {
    EnumSet<SlotType> slots = EnumSet.noneOf(SlotType.class);
    if (serialized == null || serialized.trim().isEmpty()) {
      return slots;
    }
    for (String part : serialized.split(",")) {
      String slotName = part.trim();
      if (slotName.isEmpty()) {
        continue;
      }
      try {
        slots.add(SlotType.valueOf(slotName.toUpperCase(Locale.ENGLISH)));
      } catch (IllegalArgumentException ex) {
        log.debug("Ignoring unknown slot in token snapshot: {}", slotName);
      }
    }
    return slots;
  }

  private void migrateLegacySnapshotFiles() {
    LegacySnapshot legacy = readLegacySnapshotFile();
    if (legacy == null) {
      return;
    }
    if (!legacy.bankSlots.isEmpty()) {
      applyBankTokens(legacy.bankSlots);
    }
    if (!legacy.inventorySlots.isEmpty()) {
      applyInventoryTokens(legacy.inventorySlots);
    }
    persistSnapshots();
    deleteLegacySnapshotFiles();
  }

  private LegacySnapshot readLegacySnapshotFile() {
    if (Files.isRegularFile(SNAPSHOT_FILE)) {
      try (Reader reader = Files.newBufferedReader(SNAPSHOT_FILE)) {
        Type type = new TypeToken<Map<String, Object>>() {}.getType();
        Map<String, Object> raw = gson.fromJson(reader, type);
        if (raw != null) {
          return legacyFromRaw(raw);
        }
      } catch (IOException | RuntimeException ex) {
        log.debug("Failed to load legacy snapshot from {}", SNAPSHOT_FILE, ex);
      }
    }
    if (Files.isRegularFile(LEGACY_BANK_SNAPSHOT_FILE)) {
      try (Reader reader = Files.newBufferedReader(LEGACY_BANK_SNAPSHOT_FILE)) {
        Type type = new TypeToken<Map<String, Object>>() {}.getType();
        Map<String, Object> raw = gson.fromJson(reader, type);
        if (raw != null) {
          LegacySnapshot legacy = new LegacySnapshot();
          legacy.bankSlots = slotNamesFromRaw(raw.get("slots"));
          return legacy;
        }
      } catch (IOException | RuntimeException ex) {
        log.debug("Failed to load legacy bank snapshot from {}", LEGACY_BANK_SNAPSHOT_FILE, ex);
      }
    }
    return null;
  }

  private LegacySnapshot legacyFromRaw(Map<String, Object> raw) {
    LegacySnapshot legacy = new LegacySnapshot();
    legacy.bankSlots = slotNamesFromRaw(raw.get("bankSlots"));
    legacy.inventorySlots = slotNamesFromRaw(raw.get("inventorySlots"));
    return legacy;
  }

  @SuppressWarnings("unchecked")
  private EnumSet<SlotType> slotNamesFromRaw(Object rawSlots) {
    EnumSet<SlotType> slots = EnumSet.noneOf(SlotType.class);
    if (!(rawSlots instanceof List)) {
      return slots;
    }
    for (Object entry : (List<?>) rawSlots) {
      if (entry instanceof String) {
        try {
          slots.add(SlotType.valueOf(((String) entry).toUpperCase(Locale.ENGLISH)));
        } catch (IllegalArgumentException ex) {
          log.debug("Ignoring unknown slot in legacy snapshot: {}", entry);
        }
      }
    }
    return slots;
  }

  private void deleteLegacySnapshotFiles() {
    try {
      Files.deleteIfExists(SNAPSHOT_FILE);
      Files.deleteIfExists(LEGACY_BANK_SNAPSHOT_FILE);
    } catch (IOException ex) {
      log.debug("Failed to delete legacy snapshot files", ex);
    }
  }

  private int collectTokens(ItemContainer container, EnumSet<SlotType> tokensPresent) {
    return collectTokenTypes(container, tokensPresent);
  }

  private int collectTokenTypes(ItemContainer container, EnumSet<SlotType> tokensPresent) {
    if (container == null) {
      return 0;
    }
    boolean bankContainer = container.getId() == InventoryID.BANK;
    int count = 0;
    for (Item item : container.getItems()) {
      if (item == null || item.getId() <= 0) {
        continue;
      }
      if (bankContainer && isBankPlaceholder(item)) {
        continue;
      }
      int canonicalId = itemManager.canonicalize(item.getId());
      SlotType slot = SlotType.fromTokenItemId(canonicalId);
      if (slot != null) {
        tokensPresent.add(slot);
        count += item.getQuantity();
      }
    }
    return count;
  }

  private boolean isBankPlaceholder(Item item) {
    if (item.getQuantity() <= 0) {
      return true;
    }
    return itemManager.getItemComposition(item.getId()).getPlaceholderTemplateId() != -1;
  }

  private void updateState(LocalSlotState newState) {
    if (state.getTokensPresent().equals(newState.getTokensPresent())
        && state.getTokensInGroupStorage().equals(newState.getTokensInGroupStorage())
        && state.getEquippedSlots().equals(newState.getEquippedSlots())
        && state.getEquippedItemIds().equals(newState.getEquippedItemIds())
        && state.getHeldTokenCount() == newState.getHeldTokenCount()) {
      return;
    }
    state = newState;
    for (Consumer<LocalSlotState> listener : listeners) {
      listener.accept(state);
    }
  }

  private static final class TokenTotals {
    private final EnumSet<SlotType> slots;
    private final int count;

    private TokenTotals(EnumSet<SlotType> slots, int count) {
      this.slots = slots;
      this.count = count;
    }

    private static TokenTotals from(EnumSet<SlotType> slots, int count) {
      return new TokenTotals(EnumSet.copyOf(slots), count);
    }
  }

  private static final class LegacySnapshot {
    private EnumSet<SlotType> bankSlots = EnumSet.noneOf(SlotType.class);
    private EnumSet<SlotType> inventorySlots = EnumSet.noneOf(SlotType.class);
  }
}

package com.gsl.service;

import com.gsl.GroupSlotLockedConfig;
import com.gsl.model.LocalSlotState;
import com.gsl.model.SlotType;
import com.gsl.model.ValidationResult;
import com.gsl.model.Violation;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

@Singleton
public class SlotValidator {
  /**
   * Ring-slot escape items exempt from the red "can't equip" highlight only — equipping them
   * still requires the Ring slot token like any other gear.
   */
  private static final Set<Integer> ALWAYS_ALLOWED_ITEM_IDS =
      Set.of(
          ItemID.TOB_TELEPORT, // Escape crystal (Theatre of Blood)
          ItemID.GAUNTLET_ESCAPE_CRYSTAL, // Escape crystal (The Gauntlet)
          ItemID.GAUNTLET_ESCAPE_CRYSTAL_HM); // Corrupted escape crystal (Corrupted Gauntlet)

  private final GroupSlotLockedConfig config;
  private final ItemManager itemManager;

  @Inject
  SlotValidator(GroupSlotLockedConfig config, ItemManager itemManager) {
    this.config = config;
    this.itemManager = itemManager;
  }

  public boolean hasActiveClaim(LocalSlotState state, SlotType slot) {
    return state.getHeldTokenCount() <= config.maxHeldTokens() && state.hasToken(slot);
  }

  public ValidationResult validateEquip(LocalSlotState state, int itemId) {
    return validateEquip(state, slotsForItem(itemId), config.maxHeldTokens(), config.maxEquipped());
  }

  public static ValidationResult validateEquip(
      LocalSlotState state, Set<SlotType> itemSlots, int maxHeldTokens, int maxEquipped) {
    if (itemSlots.isEmpty()) {
      return ValidationResult.ok();
    }
    if (state.getHeldTokenCount() > maxHeldTokens) {
      return ValidationResult.fail(Violation.TOO_MANY_TOKENS, null);
    }
    for (SlotType slot : itemSlots) {
      if (!state.hasToken(slot)) {
        return ValidationResult.fail(Violation.NO_SLOT_CLAIM, slot);
      }
    }
    Set<SlotType> afterEquip = simulateEquip(state.getEquippedSlots(), itemSlots);
    if (afterEquip.size() > maxEquipped) {
      return ValidationResult.fail(Violation.OVER_EQUIP_LIMIT, null);
    }
    return ValidationResult.ok();
  }

  public Violation getViolationForItem(LocalSlotState state, int itemId) {
    if (itemId <= 0 || isPlaceholderItem(itemId)) {
      return Violation.NONE;
    }
    int canonicalId = itemManager.canonicalize(itemId);
    if (SlotType.isTokenItem(canonicalId) || ALWAYS_ALLOWED_ITEM_IDS.contains(canonicalId)) {
      return Violation.NONE;
    }
    return validateEquip(state, canonicalId).getViolation();
  }

  private boolean isPlaceholderItem(int itemId) {
    return itemManager.getItemComposition(itemId).getPlaceholderTemplateId() != -1;
  }

  public List<Violation> getCurrentViolations(LocalSlotState state) {
    List<Violation> violations = new ArrayList<>();
    if (state.getHeldTokenCount() > config.maxHeldTokens()) {
      violations.add(Violation.TOO_MANY_TOKENS);
    }
    if (state.getEquippedSlots().size() > config.maxEquipped()) {
      violations.add(Violation.OVER_EQUIP_LIMIT);
    }
    if (findMissingClaimSlot(state).isPresent()) {
      violations.add(Violation.NO_SLOT_CLAIM);
    }
    if (!violations.isEmpty() && !state.getEquippedSlots().isEmpty()) {
      violations.add(Violation.CURRENTLY_ILLEGAL);
    }
    return violations;
  }

  /** First currently-equipped slot without an active token claim, if any. */
  public Optional<SlotType> findMissingClaimSlot(LocalSlotState state) {
    for (SlotType equipped : state.getEquippedSlots()) {
      if (!hasActiveClaim(state, equipped)) {
        return Optional.of(equipped);
      }
    }
    return Optional.empty();
  }

  public boolean isLoadoutIllegal(LocalSlotState state) {
    return !getCurrentViolations(state).isEmpty();
  }

  public Set<SlotType> slotsForItem(int itemId) {
    ItemStats stats = itemManager.getItemStats(itemId);
    if (stats == null || !stats.isEquipable()) {
      return EnumSet.noneOf(SlotType.class);
    }
    ItemEquipmentStats equipment = stats.getEquipment();
    if (equipment == null) {
      return EnumSet.noneOf(SlotType.class);
    }
    EnumSet<SlotType> slots = EnumSet.noneOf(SlotType.class);
    SlotType.fromEquipmentIndex(equipment.getSlot()).ifPresent(slots::add);
    if (equipment.isTwoHanded()) {
      slots.add(SlotType.MAIN_HAND);
      slots.add(SlotType.OFF_HAND);
    }
    return slots;
  }

  public static Set<SlotType> simulateEquip(
      Set<SlotType> currentlyEquipped, Set<SlotType> newItemSlots) {
    EnumSet<SlotType> result =
        currentlyEquipped == null || currentlyEquipped.isEmpty()
            ? EnumSet.noneOf(SlotType.class)
            : EnumSet.copyOf(currentlyEquipped);
    if (newItemSlots.contains(SlotType.MAIN_HAND) && newItemSlots.contains(SlotType.OFF_HAND)) {
      result.remove(SlotType.MAIN_HAND);
      result.remove(SlotType.OFF_HAND);
    } else if (newItemSlots.contains(SlotType.MAIN_HAND)) {
      result.remove(SlotType.MAIN_HAND);
      if (currentlyEquipped.contains(SlotType.MAIN_HAND)
          && currentlyEquipped.contains(SlotType.OFF_HAND)) {
        result.remove(SlotType.OFF_HAND);
      }
    } else if (newItemSlots.contains(SlotType.OFF_HAND)) {
      result.remove(SlotType.OFF_HAND);
    }
    for (SlotType slot : newItemSlots) {
      result.remove(slot);
    }
    result.addAll(newItemSlots);
    return result;
  }
}

package com.gsl.service;

import com.gsl.model.SlotType;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.events.PostItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.eventbus.Subscribe;

/**
 * Overrides the inventory model backing each slot token item with the (unused) ScapeRune
 * teleport tablet model. The icon-replacement overlay draws over these items every frame, but if
 * it ever fails to run for a particular widget/context, the fallback visual is an unrelated
 * teleport tablet instead of an obvious team cape.
 *
 * <p>{@link net.runelite.api.NodeCache} only exposes a blanket {@code reset()} — there's no public
 * API to evict a single item id from the client's composition cache. So instead of resetting the
 * whole cache (which would also discard any other plugin's unrelated composition overrides), we
 * remember the original model for exactly the item ids we touch and set it back on shutdown.
 */
@Slf4j
@Singleton
public class TokenModelOverrideService {
  private final Client client;
  private final Map<Integer, Integer> originalModelByItemId = new HashMap<>();
  private int tabletModelId = -1;

  @Inject
  TokenModelOverrideService(Client client) {
    this.client = client;
  }

  /** Must be called on the client thread. Applies the override to any already-cached compositions. */
  public void warmUp() {
    int modelId = resolveTabletModelId();
    if (modelId <= 0) {
      return;
    }
    boolean changed = false;
    for (SlotType slot : SlotType.values()) {
      ItemComposition composition = client.getItemDefinition(slot.getTokenItemId());
      changed |= applyOverride(composition, modelId);
      int placeholderId = composition.getPlaceholderId();
      if (placeholderId > 0 && placeholderId != slot.getTokenItemId()) {
        changed |= applyOverride(client.getItemDefinition(placeholderId), modelId);
      }
    }
    if (changed) {
      flushCaches();
    }
  }

  /** Must be called on the client thread. Puts back the original model for any item we overrode. */
  public void restore() {
    if (originalModelByItemId.isEmpty()) {
      return;
    }
    boolean changed = false;
    for (Map.Entry<Integer, Integer> entry : originalModelByItemId.entrySet()) {
      ItemComposition composition = client.getItemDefinition(entry.getKey());
      if (composition.getInventoryModel() != entry.getValue()) {
        composition.setInventoryModel(entry.getValue());
        changed = true;
      }
    }
    originalModelByItemId.clear();
    if (changed) {
      flushCaches();
    }
  }

  @Subscribe
  public void onPostItemComposition(PostItemComposition event) {
    ItemComposition composition = event.getItemComposition();
    if (!isTokenComposition(composition)) {
      return;
    }
    int modelId = resolveTabletModelId();
    if (modelId <= 0) {
      return;
    }
    if (applyOverride(composition, modelId)) {
      flushCaches();
    }
  }

  private boolean isTokenComposition(ItemComposition composition) {
    if (SlotType.isTokenItem(composition.getId())) {
      return true;
    }
    int templateId = composition.getPlaceholderTemplateId();
    return templateId != -1 && SlotType.isTokenItem(composition.getPlaceholderId());
  }

  private boolean applyOverride(ItemComposition composition, int modelId) {
    if (composition.getInventoryModel() == modelId) {
      return false;
    }
    originalModelByItemId.putIfAbsent(composition.getId(), composition.getInventoryModel());
    composition.setInventoryModel(modelId);
    return true;
  }

  private int resolveTabletModelId() {
    if (tabletModelId > 0) {
      return tabletModelId;
    }
    ItemComposition tablet = client.getItemDefinition(ItemID.XMAS19_TABLET_SCAPE_RUNE);
    tabletModelId = tablet.getInventoryModel();
    if (tabletModelId <= 0) {
      log.debug("Could not resolve ScapeRune tablet inventory model");
    }
    return tabletModelId;
  }

  private void flushCaches() {
    client.getItemModelCache().reset();
    client.getItemSpriteCache().reset();
  }
}

package com.gsl.service;

import com.gsl.GroupSlotLockedConfig;
import com.gsl.model.LocalSlotState;
import com.gsl.model.SlotType;
import com.gsl.model.Violation;
import java.awt.Color;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.util.ColorUtil;

@Singleton
public class ViolationNotifier {
  private final GroupSlotLockedConfig config;
  private final SlotValidator slotValidator;
  private final SlotDisplayService displayService;
  private final ChatMessageManager chatMessageManager;
  private boolean wasIllegal;
  private boolean wasOverTokenCap;

  @Inject
  ViolationNotifier(
      GroupSlotLockedConfig config,
      SlotValidator slotValidator,
      SlotDisplayService displayService,
      ChatMessageManager chatMessageManager) {
    this.config = config;
    this.slotValidator = slotValidator;
    this.displayService = displayService;
    this.chatMessageManager = chatMessageManager;
  }

  public void onStateChanged(LocalSlotState state) {
    // Only treat the loadout as "illegal" (for chat purposes) when something is actually
    // equipped illegally — TOO_MANY_TOKENS alone (e.g. holding an extra token with nothing
    // worn) is already fully covered by the over-cap message below, and would otherwise fire
    // both every time.
    boolean illegal =
        slotValidator.getCurrentViolations(state).contains(Violation.CURRENTLY_ILLEGAL);
    boolean overTokenCap = state.getHeldTokenCount() > config.maxHeldTokens();
    if (!config.chatWarnings()) {
      wasIllegal = illegal;
      wasOverTokenCap = overTokenCap;
      return;
    }
    if (overTokenCap && !wasOverTokenCap) {
      queueMessage(
          "You're holding "
              + state.getHeldTokenCount()
              + " slot tokens, but you can only hold "
              + config.maxHeldTokens()
              + ". Store one in group storage.");
    }
    if (illegal && !wasIllegal) {
      queueMessage(buildIllegalMessage(state));
    }
    wasIllegal = illegal;
    wasOverTokenCap = overTokenCap;
  }

  public void reset() {
    wasIllegal = false;
    wasOverTokenCap = false;
  }

  private String buildIllegalMessage(LocalSlotState state) {
    for (Violation violation : slotValidator.getCurrentViolations(state)) {
      switch (violation) {
        case TOO_MANY_TOKENS:
          return "You're holding too many slot tokens.";
        case OVER_EQUIP_LIMIT:
          return "You have too many items equipped.";
        case NO_SLOT_CLAIM:
          return buildMissingClaimMessage(state);
        default:
          break;
      }
    }
    return "You're wearing illegal equipment. Unequip the restricted gear.";
  }

  private String buildMissingClaimMessage(LocalSlotState state) {
    SlotType missing = slotValidator.findMissingClaimSlot(state).orElse(null);
    if (missing == null) {
      return "You're wearing illegal equipment because you're missing a slot token.";
    }
    int mainHandId = state.getEquippedItemId(SlotType.MAIN_HAND);
    int offHandId = state.getEquippedItemId(SlotType.OFF_HAND);
    if (missing == SlotType.OFF_HAND && mainHandId > 0 && mainHandId == offHandId) {
      return "Your two-handed weapon needs both the "
          + displayService.getDisplayName(SlotType.MAIN_HAND).toLowerCase()
          + " and "
          + displayService.getDisplayName(SlotType.OFF_HAND).toLowerCase()
          + " slot tokens. You're missing the "
          + displayService.getDisplayName(SlotType.OFF_HAND).toLowerCase()
          + " token.";
    }
    return "You cannot equip anything in the "
        + displayService.getDisplayName(missing).toLowerCase()
        + " slot without the slot token.";
  }

  private void queueMessage(String message) {
    chatMessageManager.queue(
        QueuedMessage.builder()
            .type(ChatMessageType.GAMEMESSAGE)
            .runeLiteFormattedMessage(ColorUtil.wrapWithColorTag(message, Color.RED))
            .build());
  }
}

package com.gsl.util;

import com.gsl.model.SlotType;
import javax.annotation.Nullable;
import net.runelite.client.game.ItemManager;

public final class BankItemUtils {
  private BankItemUtils() {}

  public static boolean isPlaceholderItem(ItemManager itemManager, int itemId, int quantity) {
    if (itemId <= 0) {
      return false;
    }
    if (quantity <= 0 || quantity == Integer.MAX_VALUE) {
      return true;
    }
    return itemManager.getItemComposition(itemId).getPlaceholderTemplateId() != -1;
  }

  /**
   * Bank placeholders often store quantity 1 internally while the UI shows 0. Bank tag layout
   * slots with no matching bank item use the real (non-placeholder) item ID but set quantity to
   * {@link Integer#MAX_VALUE} with {@code ItemQuantityMode.NEVER} as a sentinel meaning "no
   * quantity" (see LayoutManager#drawItem in RuneLite).
   */
  public static int resolvePlaceholderDisplayQuantity(
      ItemManager itemManager, int itemId, int quantity) {
    if (itemId <= 0) {
      return quantity;
    }
    if (quantity <= 0 || quantity == Integer.MAX_VALUE) {
      return 0;
    }
    if (itemManager.getItemComposition(itemId).getPlaceholderTemplateId() != -1) {
      return 0;
    }
    return quantity;
  }

  @Nullable
  public static SlotType resolveSlotType(ItemManager itemManager, int itemId) {
    if (itemId <= 0) {
      return null;
    }
    SlotType slot = SlotType.fromTokenItemId(itemManager.canonicalize(itemId));
    if (slot != null) {
      return slot;
    }
    int templateId = itemManager.getItemComposition(itemId).getPlaceholderTemplateId();
    if (templateId != -1) {
      return SlotType.fromTokenItemId(itemManager.canonicalize(templateId));
    }
    return null;
  }
}

package com.gsl.util;

import com.gsl.model.SlotType;
import com.gsl.model.TokenIconRenderContext;
import com.gsl.model.TokenIconStyle;
import com.gsl.service.SlotDisplayService;
import com.gsl.util.BankItemUtils;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.function.Predicate;
import javax.annotation.Nullable;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;

public final class TokenDragIconRenderer {
  private static final int DRAG_ICON_SIZE = 36;
  private static Point dragGrabOffset;
  private static int dragGrabSourceId = -1;
  private static Point inventoryHoldAnchorMouse;
  private static int inventoryHoldAnchorSourceId = -1;
  private static Point bankHoldAnchorMouse;
  private static int bankHoldAnchorSourceId = -1;
  private static boolean dragHandoffReady;
  private static int dragHandoffSourceId = -1;
  private static final int DRAG_MOVE_THRESHOLD_SQ = 4;
  private static final int[] BANK_ITEM_CONTAINERS = {
    InterfaceID.Bankmain.ITEMS,
    InterfaceID.SharedBank.ITEMS,
    InterfaceID.Bankmain.BANKTAGS_DISPLAY_ITEMS,
  };
  private static final int[] BANK_DRAG_LAYERS = {
    InterfaceID.Bankmain.BANKTAGS_DISPLAY_DRAGLAYER,
  };
  private static final int[] BANK_MAIN_ITEM_CONTAINERS = {
    InterfaceID.Bankmain.ITEMS,
    InterfaceID.Bankmain.BANKTAGS_DISPLAY_ITEMS,
    InterfaceID.SharedBank.ITEMS,
    InterfaceID.Bankmain.TABS,
  };
  // SharedBankSide.ITEMS is deliberately excluded here: its drawAfterLayer hook never fires
  // for a stationary (non-moving) press, so that case is handled exclusively by
  // renderSharedBankSideStationaryHoldCover() on the ALWAYS_ON_TOP layer instead.
  private static final int[] INVENTORY_ITEM_CONTAINERS = {
    InterfaceID.Inventory.ITEMS, InterfaceID.Bankside.ITEMS, InterfaceID.Tradeside.SIDE_LAYER,
  };

  private TokenDragIconRenderer() {}

  public static void renderStaticWidgetItemIcon(
      Graphics2D graphics,
      ItemManager itemManager,
      SlotDisplayService displayService,
      int itemId,
      WidgetItem widgetItem) {
    SlotType slot = slotFromItemId(itemManager, itemId);
    if (slot == null) {
      return;
    }
    drawTokenIcon(
        graphics,
        itemManager,
        displayService,
        slot,
        widgetItem.getCanvasBounds(false),
        itemId,
        widgetItem.getQuantity(),
        TokenIconRenderContext.STATIC);
  }

  public static void renderWidgetItemIcon(
      Graphics2D graphics,
      Client client,
      ItemManager itemManager,
      SlotDisplayService displayService,
      int itemId,
      WidgetItem widgetItem) {
    SlotType slot = slotFromItemId(itemManager, itemId);
    if (slot == null) {
      return;
    }

    if (shouldHideStaticIconDuringDrag(client, widgetItem)) {
      return;
    }

    renderStaticWidgetItemIcon(graphics, itemManager, displayService, itemId, widgetItem);
  }

  public static void renderInventoryInterfaceItemIcon(
      Graphics2D graphics,
      Client client,
      ItemManager itemManager,
      SlotDisplayService displayService,
      int itemId,
      WidgetItem widgetItem) {
    if (isBankMainSourceWidget(widgetItem.getWidget())) {
      return;
    }
    if (tryRenderStationaryHoldWidgetCover(
        graphics, client, itemManager, displayService, widgetItem, false)) {
      return;
    }
    if (!shouldDrawDragGhost(client, widgetItem)) {
      return;
    }
    renderDragWidgetItemIconWithHeldFallback(
        graphics, client, itemManager, displayService, itemId, widgetItem);
  }

  public static void renderBankInterfaceItemIcon(
      Graphics2D graphics,
      Client client,
      ItemManager itemManager,
      SlotDisplayService displayService,
      int itemId,
      WidgetItem widgetItem) {
    if (!isBankMainSourceWidget(widgetItem.getWidget())) {
      return;
    }
    if (tryRenderStationaryHoldWidgetCover(
        graphics, client, itemManager, displayService, widgetItem, true)) {
      return;
    }
    if (!shouldDrawDragGhost(client, widgetItem)) {
      return;
    }
    renderDragWidgetItemIconWithHeldFallback(
        graphics, client, itemManager, displayService, itemId, widgetItem);
  }

  public static void renderStationaryHoldCover(
      Graphics2D graphics,
      Client client,
      ItemManager itemManager,
      SlotDisplayService displayService) {
    if (!isLeftClickPressHold(client)) {
      clearInventoryHoldAnchor();
      clearBankHoldAnchor();
      clearDragHandoffState();
      return;
    }

    Widget dragged = client.getDraggedWidget();
    if (dragged != null) {
      if (isInventoryDragContainer(dragged)) {
        renderSourceSlotHoldCover(graphics, client, itemManager, displayService, dragged, false);
      } else if (isBankMainDragSource(dragged)) {
        renderSourceSlotHoldCover(graphics, client, itemManager, displayService, dragged, true);
      }
      return;
    }

    Point mouse = client.getMouseCanvasPosition();
    if (mouse == null) {
      return;
    }

    for (int containerId : INVENTORY_ITEM_CONTAINERS) {
      if (drawStationaryHoldAtContainer(
          graphics,
          client,
          itemManager,
          displayService,
          containerId,
          mouse.getX(),
          mouse.getY())) {
        return;
      }
    }

    for (int containerId : BANK_ITEM_CONTAINERS) {
      if (drawStationaryHoldAtContainer(
          graphics,
          client,
          itemManager,
          displayService,
          containerId,
          mouse.getX(),
          mouse.getY())) {
        return;
      }
    }
  }

  private static boolean tryRenderStationaryHoldWidgetCover(
      Graphics2D graphics,
      Client client,
      ItemManager itemManager,
      SlotDisplayService displayService,
      WidgetItem widgetItem,
      boolean bankMain) {
    if (!isStationaryHoldWidgetItem(client, widgetItem, bankMain)) {
      return false;
    }
    HeldItemDetails held = resolveHeldItemDetails(client, itemManager, client.getDraggedWidget());
    if (held == null) {
      int itemId = widgetItem.getId();
      if (slotFromItemId(itemManager, itemId) == null) {
        return false;
      }
      held = new HeldItemDetails(itemId, widgetItem.getQuantity());
    }
    if (slotFromItemId(itemManager, held.itemId) == null) {
      return false;
    }
    held =
        new HeldItemDetails(
            held.itemId,
            BankItemUtils.resolvePlaceholderDisplayQuantity(
                itemManager, held.itemId, held.quantity));
    drawStationaryHoldAtWidget(
        graphics,
        client,
        itemManager,
        displayService,
        held,
        widgetItem.getWidget(),
        TokenIconRenderContext.PRESSED_IN_SLOT);
    return true;
  }

  private static void renderSourceSlotHoldCover(
      Graphics2D graphics,
      Client client,
      ItemManager itemManager,
      SlotDisplayService displayService,
      Widget dragged,
      boolean bankMain) {
    if (needsSourceSlotHoldCover(client, dragged, bankMain)) {
      drawStationaryHoldForDrag(
          graphics, client, itemManager, displayService, dragged, bankMain);
    }
  }

  private static boolean needsSourceSlotHoldCover(Client client, Widget dragged, boolean bankMain) {
    if (!isLeftClickPressHold(client)) {
      return false;
    }
    if (bankMain) {
      if (!isBankMainDragSource(dragged)) {
        return false;
      }
    } else if (!isInventoryDragContainer(dragged)) {
      return false;
    }
    return !isDragHandoffReady(client);
  }

  private static boolean isDragHandoffReady(Client client) {
    Widget dragged = client.getDraggedWidget();
    if (dragged == null || !dragHandoffReady) {
      return false;
    }
    return dragHandoffSourceId == (dragged.getId() << 16 | dragged.getIndex());
  }

  private static void markDragHandoffReady(Client client) {
    Widget dragged = client.getDraggedWidget();
    if (dragged == null) {
      return;
    }
    dragHandoffReady = true;
    dragHandoffSourceId = dragged.getId() << 16 | dragged.getIndex();
  }

  private static void clearDragHandoffState() {
    dragHandoffReady = false;
    dragHandoffSourceId = -1;
  }

  private static boolean isStationaryHoldDrag(Client client, Widget dragged, boolean bankMain) {
    if (!needsSourceSlotHoldCover(client, dragged, bankMain)) {
      return false;
    }
    return bankMain
        ? !hasVisualBankDragStarted(client, dragged)
        : !hasVisualInventoryDragStarted(client, dragged);
  }

  private static boolean isStationaryHoldWidgetItem(
      Client client, WidgetItem widgetItem, boolean bankMain) {
    if (!isLeftClickPressHold(client)) {
      return false;
    }
    Widget itemWidget = widgetItem.getWidget();
    if (bankMain) {
      if (!isBankMainSourceWidget(itemWidget)) {
        return false;
      }
    } else if (isBankMainSourceWidget(itemWidget)) {
      return false;
    }

    Widget dragged = client.getDraggedWidget();
    if (dragged == null || !isStationaryHoldDrag(client, dragged, bankMain)) {
      return false;
    }
    if (bankMain && !isBankMainDragSource(dragged)) {
      return false;
    }
    if (!bankMain && !isInventoryDragContainer(dragged)) {
      return false;
    }
    Widget heldSlot = resolveDraggedSlotWidget(client);
    return heldSlot != null && heldSlot == itemWidget;
  }

  private static void drawStationaryHoldForDrag(
      Graphics2D graphics,
      Client client,
      ItemManager itemManager,
      SlotDisplayService displayService,
      Widget dragged,
      boolean bankMain) {
    HeldItemDetails held = resolveHeldItemDetails(client, itemManager, dragged);
    if (held == null || slotFromItemId(itemManager, held.itemId) == null) {
      return;
    }
    Widget heldSlot = resolveDraggedSlotWidget(client);
    TokenIconRenderContext context =
        isStationaryHoldDrag(client, dragged, bankMain)
            ? TokenIconRenderContext.PRESSED_IN_SLOT
            : TokenIconRenderContext.SOURCE_LAYER_COVER;
    drawStationaryHoldAtWidget(
        graphics,
        client,
        itemManager,
        displayService,
        held,
        heldSlot != null ? heldSlot : dragged,
        context);
  }

  private static void drawStationaryHoldAtWidget(
      Graphics2D graphics,
      Client client,
      ItemManager itemManager,
      SlotDisplayService displayService,
      HeldItemDetails held,
      @Nullable Widget slotWidget,
      TokenIconRenderContext context) {
    SlotType slot = slotFromItemId(itemManager, held.itemId);
    if (slot == null) {
      return;
    }
    Rectangle bounds = slotWidget != null ? getWidgetCanvasBounds(client, slotWidget) : null;
    if (bounds != null) {
      drawTokenIcon(
          graphics,
          itemManager,
          displayService,
          slot,
          bounds,
          held.itemId,
          held.quantity,
          context);
    }
  }

  private static void renderDragWidgetItemIconWithHeldFallback(
      Graphics2D graphics,
      Client client,
      ItemManager itemManager,
      SlotDisplayService displayService,
      int itemId,
      WidgetItem widgetItem) {
    int quantity = widgetItem.getQuantity();
    if (slotFromItemId(itemManager, itemId) == null) {
      HeldItemDetails held = resolveHeldItemDetails(client, itemManager, client.getDraggedWidget());
      if (held == null || slotFromItemId(itemManager, held.itemId) == null) {
        return;
      }
      itemId = held.itemId;
      quantity = held.quantity;
    }
    renderDragWidgetItemIcon(
        graphics, client, itemManager, displayService, itemId, quantity, widgetItem);
  }

  private static boolean drawStationaryHoldAtContainer(
      Graphics2D graphics,
      Client client,
      ItemManager itemManager,
      SlotDisplayService displayService,
      int containerId,
      int mouseX,
      int mouseY) {
    Widget container = client.getWidget(containerId);
    Widget hit = findItemChildAtCanvas(client, container, mouseX, mouseY);
    if (hit == null) {
      return false;
    }
    HeldItemDetails held = resolveHeldItemDetails(client, itemManager, null, hit);
    if (held == null || slotFromItemId(itemManager, held.itemId) == null) {
      return false;
    }
    drawStationaryHoldAtWidget(
        graphics,
        client,
        itemManager,
        displayService,
        held,
        hit,
        TokenIconRenderContext.PRESSED_IN_SLOT);
    return true;
  }

  @Nullable
  private static HeldItemDetails resolveHeldItemDetails(
      Client client, ItemManager itemManager, Widget dragged) {
    return resolveHeldItemDetails(
        client, itemManager, dragged, resolveDraggedSlotWidget(client));
  }

  @Nullable
  private static HeldItemDetails resolveHeldItemDetails(
      Client client,
      ItemManager itemManager,
      @Nullable Widget dragged,
      @Nullable Widget heldSlot) {
    if (dragged != null) {
      ItemContainer container = containerForDragWidget(client, dragged.getId());
      if (container != null) {
        Item item = container.getItem(dragged.getIndex());
        if (item != null && item.getId() > 0) {
          int quantity =
              BankItemUtils.resolvePlaceholderDisplayQuantity(
                  itemManager, item.getId(), item.getQuantity());
          return new HeldItemDetails(item.getId(), quantity);
        }
      }
    }

    int itemId = heldSlot != null ? heldSlot.getItemId() : -1;
    int quantity = heldSlot != null ? heldSlot.getItemQuantity() : 0;
    if (itemId <= 0) {
      return null;
    }
    quantity =
        BankItemUtils.resolvePlaceholderDisplayQuantity(itemManager, itemId, quantity);
    return new HeldItemDetails(itemId, quantity);
  }

  @Nullable
  private static ItemContainer containerForDragWidget(Client client, int widgetId) {
    if (widgetId == InterfaceID.Inventory.ITEMS
        || widgetId == InterfaceID.Bankside.ITEMS
        || widgetId == InterfaceID.Tradeside.SIDE_LAYER) {
      return client.getItemContainer(InventoryID.INV);
    }
    if (widgetId == InterfaceID.Bankmain.ITEMS
        || widgetId == InterfaceID.Bankmain.BANKTAGS_DISPLAY_ITEMS) {
      return client.getItemContainer(InventoryID.BANK);
    }
    if (widgetId == InterfaceID.SharedBank.ITEMS
        || widgetId == InterfaceID.SharedBankSide.ITEMS) {
      return client.getItemContainer(InventoryID.INV_GROUP_TEMP);
    }
    return null;
  }

  private static final class HeldItemDetails {
    private final int itemId;
    private final int quantity;

    private HeldItemDetails(int itemId, int quantity) {
      this.itemId = itemId;
      this.quantity = quantity;
    }
  }

  private static void renderDragWidgetItemIcon(
      Graphics2D graphics,
      Client client,
      ItemManager itemManager,
      SlotDisplayService displayService,
      int itemId,
      int quantity,
      WidgetItem widgetItem) {
    SlotType slot = slotFromItemId(itemManager, itemId);
    if (slot == null) {
      return;
    }

    Rectangle dragBounds = widgetItem.getDraggingCanvasBounds();
    if (dragBounds == null) {
      dragBounds =
          resolveDragBounds(
              client, widgetItem.getWidget(), widgetItem.getCanvasBounds(false));
    }
    if (dragBounds != null) {
      if (widgetItem.getDraggingCanvasBounds() != null) {
        markDragHandoffReady(client);
      }
      drawTokenIcon(
          graphics,
          itemManager,
          displayService,
          slot,
          dragBounds,
          itemId,
          quantity,
          TokenIconRenderContext.DRAG_AT_CURSOR);
    }
  }

  private static boolean shouldDrawDragGhost(Client client, WidgetItem widgetItem) {
    if (widgetItem.getDraggingCanvasBounds() != null) {
      return true;
    }
    Widget draggedSlot = resolveDraggedSlotWidget(client);
    Widget itemWidget = widgetItem.getWidget();
    if (draggedSlot == null || itemWidget == null || draggedSlot != itemWidget) {
      return false;
    }
    Widget dragged = client.getDraggedWidget();
    if (dragged != null && isInventoryDragContainer(dragged)) {
      return hasVisualInventoryDragStarted(client, dragged);
    }
    if (dragged != null && isBankMainDragSource(dragged)) {
      return hasVisualBankDragStarted(client, dragged);
    }
    return false;
  }

  private static boolean shouldHideStaticIconDuringDrag(Client client, WidgetItem widgetItem) {
    if (widgetItem.getDraggingCanvasBounds() != null) {
      return true;
    }
    Widget draggedSlot = resolveDraggedSlotWidget(client);
    Widget itemWidget = widgetItem.getWidget();
    if (draggedSlot == null || itemWidget == null || draggedSlot != itemWidget) {
      return false;
    }
    Widget dragged = client.getDraggedWidget();
    if (dragged == null) {
      return false;
    }
    boolean bankMain = isBankMainSourceWidget(itemWidget);
    return needsSourceSlotHoldCover(client, dragged, bankMain);
  }

  @Nullable
  private static Widget findItemChildAtCanvas(
      Client client, Widget container, int canvasX, int canvasY) {
    if (container == null) {
      return null;
    }
    Widget hit = findInChildrenAtCanvas(client, container.getDynamicChildren(), canvasX, canvasY);
    if (hit != null) {
      return hit;
    }
    return findInChildrenAtCanvas(client, container.getChildren(), canvasX, canvasY);
  }

  @Nullable
  private static Widget findInChildrenAtCanvas(
      Client client, Widget[] children, int canvasX, int canvasY) {
    if (children == null) {
      return null;
    }
    for (Widget child : children) {
      if (child == null || child.isHidden() || child.getItemId() <= 0) {
        continue;
      }
      Rectangle bounds = getWidgetCanvasBounds(client, child);
      if (bounds != null && bounds.contains(canvasX, canvasY)) {
        return child;
      }
    }
    return null;
  }

  @Nullable
  private static Widget resolveDraggedSlotWidget(Client client) {
    Widget dragged = client.getDraggedWidget();
    if (dragged == null) {
      return null;
    }
    int id = dragged.getId();
    if (id == InterfaceID.Inventory.ITEMS
        || id == InterfaceID.Bankside.ITEMS
        || id == InterfaceID.SharedBankSide.ITEMS
        || id == InterfaceID.Bankmain.ITEMS
        || id == InterfaceID.SharedBank.ITEMS
        || id == InterfaceID.Bankmain.BANKTAGS_DISPLAY_ITEMS
        || id == InterfaceID.Tradeside.SIDE_LAYER) {
      return dragged.getChild(dragged.getIndex());
    }
    return dragged;
  }

  public static void renderDraggedWidgetIcon(
      Graphics2D graphics,
      Client client,
      ItemManager itemManager,
      SlotDisplayService displayService) {
    if (client.getDraggedWidget() == null) {
      clearDragGrabOffset();
    }
    renderBankDragLayerIcons(graphics, client, itemManager, displayService);
    // Scoped to just the two containers confirmed to need a redundant ALWAYS_ON_TOP pass
    // (see javadoc below) — NOT the broad isBankMainDragSource/isInventoryDragContainer checks.
    // Doubling this pass over contexts where the drawAfterInterface ghost already renders
    // correctly (regular inventory, regular bank grid) draws a second, slightly-offset icon
    // because this pass's mouse-tracked bounds don't exactly match the game's own
    // WidgetItem#getDraggingCanvasBounds() — visible as a lagging duplicate, not harmless.
    renderActiveDragGhost(
        graphics,
        client,
        itemManager,
        displayService,
        dragged -> dragged.getId() == InterfaceID.Bankmain.TABS);
    renderActiveDragGhost(
        graphics,
        client,
        itemManager,
        displayService,
        dragged -> dragged.getId() == InterfaceID.SharedBankSide.ITEMS);
    renderSharedBankSideStationaryHoldCover(graphics, client, itemManager, displayService);
  }

  /**
   * Covers the raw item sprite during a stationary (not-yet-moved) click-and-hold on the
   * inventory panel while group storage is open. Unlike every other stationary-hold context,
   * which is covered by {@link TokenPressHoldOverlay}'s {@code drawAfterLayer} pass,
   * SharedBankSide.ITEMS's item layer does not appear to redraw on a truly stationary press, so
   * that hook never fires here — this is the sole mechanism for this one container, not a
   * redundant fallback.
   */
  private static void renderSharedBankSideStationaryHoldCover(
      Graphics2D graphics,
      Client client,
      ItemManager itemManager,
      SlotDisplayService displayService) {
    if (!isLeftClickPressHold(client)) {
      return;
    }
    Widget dragged = client.getDraggedWidget();
    if (dragged == null || dragged.getId() != InterfaceID.SharedBankSide.ITEMS) {
      return;
    }
    renderSourceSlotHoldCover(graphics, client, itemManager, displayService, dragged, false);
  }

  /**
   * {@link TokenBankDragOverlay}/{@link TokenInventoryDragOverlay}'s ghost draws via {@code
   * drawAfterInterface}, which some UI chrome (the bank tab header bar, or the inventory side
   * panel while group storage is open) still paints over while the drag crosses into it — the raw
   * client drag sprite renders later than that and shows through. Redraw the ghost here too, on
   * {@link net.runelite.client.ui.overlay.OverlayLayer#ALWAYS_ON_TOP}, so there's always a pass
   * guaranteed to land after everything else.
   */
  private static void renderActiveDragGhost(
      Graphics2D graphics,
      Client client,
      ItemManager itemManager,
      SlotDisplayService displayService,
      Predicate<Widget> isDragSource) {
    Widget dragged = client.getDraggedWidget();
    if (dragged == null || !isDragSource.test(dragged)) {
      return;
    }
    HeldItemDetails held = resolveHeldItemDetails(client, itemManager, dragged);
    if (held == null) {
      return;
    }
    SlotType slot = slotFromItemId(itemManager, held.itemId);
    if (slot == null) {
      return;
    }
    Widget heldSlot = resolveDraggedSlotWidget(client);
    Rectangle dragBounds = resolveActiveDragBounds(client, heldSlot != null ? heldSlot : dragged);
    if (dragBounds == null) {
      return;
    }
    drawTokenIcon(
        graphics,
        itemManager,
        displayService,
        slot,
        dragBounds,
        held.itemId,
        held.quantity,
        TokenIconRenderContext.DRAG_AT_CURSOR);
  }

  public static boolean renderBankDragLayerIcons(
      Graphics2D graphics,
      Client client,
      ItemManager itemManager,
      SlotDisplayService displayService) {
    boolean drew = false;
    for (int layerId : BANK_DRAG_LAYERS) {
      Widget layer = client.getWidget(layerId);
      if (layer == null || layer.isHidden()) {
        continue;
      }
      if (renderTokenChildrenOnLayer(graphics, client, itemManager, displayService, layer)) {
        drew = true;
      }
    }
    return drew;
  }

  public static void drawTokenIcon(
      Graphics2D graphics,
      ItemManager itemManager,
      SlotDisplayService displayService,
      SlotType slot,
      Rectangle bounds,
      int itemId,
      int quantity) {
    drawTokenIcon(
        graphics,
        itemManager,
        displayService,
        slot,
        bounds,
        itemId,
        quantity,
        TokenIconRenderContext.STATIC);
  }

  public static void drawTokenIcon(
      Graphics2D graphics,
      ItemManager itemManager,
      SlotDisplayService displayService,
      SlotType slot,
      Rectangle bounds,
      int itemId,
      int quantity,
      TokenIconRenderContext context) {
    if (bounds == null) {
      return;
    }
    int displayQuantity =
        BankItemUtils.resolvePlaceholderDisplayQuantity(itemManager, itemId, quantity);
    boolean placeholder =
        BankItemUtils.isPlaceholderItem(itemManager, itemId, displayQuantity);
    TokenIconStyle style = TokenIconStyle.forContext(context, placeholder);
    displayService.drawReplacementIcon(graphics, slot, bounds, style);
    if (placeholder) {
      displayService.drawPlaceholderQuantity(graphics, bounds, displayQuantity);
    } else {
      displayService.drawItemQuantity(graphics, bounds, displayQuantity);
    }
  }

  private static boolean renderTokenChildrenOnLayer(
      Graphics2D graphics,
      Client client,
      ItemManager itemManager,
      SlotDisplayService displayService,
      Widget layer) {
    boolean drew = false;
    if (renderTokenChildren(graphics, client, itemManager, displayService, layer.getDynamicChildren())) {
      drew = true;
    }
    if (renderTokenChildren(graphics, client, itemManager, displayService, layer.getChildren())) {
      drew = true;
    }
    return drew;
  }

  private static boolean renderTokenChildren(
      Graphics2D graphics,
      Client client,
      ItemManager itemManager,
      SlotDisplayService displayService,
      Widget[] children) {
    if (children == null) {
      return false;
    }
    boolean drew = false;
    for (Widget child : children) {
      if (child == null || child.getItemId() <= 0) {
        continue;
      }
      SlotType slot = slotFromItemId(itemManager, child.getItemId());
      if (slot == null) {
        continue;
      }
      Rectangle bounds = getWidgetCanvasBounds(client, child);
      if (bounds == null) {
        bounds = resolveDragBounds(client, child, widgetSlotBounds(client, child));
      }
      if (bounds != null) {
        drawTokenIcon(
            graphics,
            itemManager,
            displayService,
            slot,
            bounds,
            child.getItemId(),
            child.getItemQuantity(),
            TokenIconRenderContext.DRAG_AT_CURSOR);
        drew = true;
      }
    }
    return drew;
  }

  private static boolean isBankMainSourceWidget(@Nullable Widget widget) {
    if (widget == null) {
      return false;
    }
    Widget current = widget;
    while (current != null) {
      int id = current.getId();
      for (int containerId : BANK_MAIN_ITEM_CONTAINERS) {
        if (id == containerId) {
          return true;
        }
      }
      current = current.getParent();
    }
    return false;
  }

  private static boolean isInventoryDragContainer(Widget dragged) {
    int id = dragged.getId();
    return id == InterfaceID.Inventory.ITEMS
        || id == InterfaceID.Bankside.ITEMS
        || id == InterfaceID.SharedBankSide.ITEMS
        || id == InterfaceID.Tradeside.SIDE_LAYER;
  }

  @Nullable
  private static Rectangle resolveActiveDragBounds(Client client, Widget draggedSlot) {
    return resolveDragBounds(client, draggedSlot, widgetSlotBounds(client, draggedSlot));
  }

  @Nullable
  private static Rectangle resolveDragBounds(
      Client client, @Nullable Widget slotWidget, @Nullable Rectangle slotBounds) {
    Point mouse = client.getMouseCanvasPosition();
    if (mouse == null) {
      return null;
    }

    if (slotBounds == null && slotWidget != null) {
      slotBounds = widgetSlotBounds(client, slotWidget);
    }

    int width = DRAG_ICON_SIZE;
    int height = DRAG_ICON_SIZE;
    if (slotBounds != null) {
      width = slotBounds.width;
      height = slotBounds.height;
    } else if (slotWidget != null && slotWidget.getWidth() > 0 && slotWidget.getHeight() > 0) {
      width = slotWidget.getWidth();
      height = slotWidget.getHeight();
    }

    Point grabOffset = getDragGrabOffset(client, slotBounds);
    return new Rectangle(
        mouse.getX() - grabOffset.getX(), mouse.getY() - grabOffset.getY(), width, height);
  }

  @Nullable
  private static Rectangle widgetSlotBounds(Client client, Widget slotWidget) {
    if (slotWidget == null) {
      return null;
    }
    Point location = slotWidget.getCanvasLocation();
    if (location != null && slotWidget.getWidth() > 0 && slotWidget.getHeight() > 0) {
      return new Rectangle(
          location.getX(), location.getY(), slotWidget.getWidth(), slotWidget.getHeight());
    }
    return getWidgetCanvasBounds(client, slotWidget);
  }

  private static Point getDragGrabOffset(Client client, @Nullable Rectangle slotBounds) {
    Widget dragged = client.getDraggedWidget();
    if (dragged == null) {
      clearDragGrabOffset();
      return new Point(0, 0);
    }

    int sourceId = dragged.getId() << 16 | dragged.getIndex();
    if (dragGrabOffset == null || dragGrabSourceId != sourceId) {
      Point anchor = getHoldAnchorMouse(client, dragged);
      Point mouse = anchor != null ? anchor : client.getMouseCanvasPosition();
      if (mouse != null && slotBounds != null) {
        dragGrabOffset = new Point(mouse.getX() - slotBounds.x, mouse.getY() - slotBounds.y);
      } else {
        dragGrabOffset = new Point(0, 0);
      }
      dragGrabSourceId = sourceId;
    }

    return dragGrabOffset;
  }

  @Nullable
  private static Point getHoldAnchorMouse(Client client, Widget dragged) {
    int sourceId = dragged.getId() << 16 | dragged.getIndex();
    if (isInventoryDragContainer(dragged)) {
      if (inventoryHoldAnchorMouse != null && inventoryHoldAnchorSourceId == sourceId) {
        return inventoryHoldAnchorMouse;
      }
    } else if (isBankMainDragSource(dragged)) {
      if (bankHoldAnchorMouse != null && bankHoldAnchorSourceId == sourceId) {
        return bankHoldAnchorMouse;
      }
    }
    return null;
  }

  private static void clearDragGrabOffset() {
    dragGrabOffset = null;
    dragGrabSourceId = -1;
  }

  private static void clearInventoryHoldAnchor() {
    inventoryHoldAnchorMouse = null;
    inventoryHoldAnchorSourceId = -1;
  }

  private static void clearBankHoldAnchor() {
    bankHoldAnchorMouse = null;
    bankHoldAnchorSourceId = -1;
  }

  private static boolean hasVisualInventoryDragStarted(Client client, Widget dragged) {
    if (!isInventoryDragContainer(dragged)) {
      return false;
    }
    Point mouse = client.getMouseCanvasPosition();
    if (mouse == null) {
      return false;
    }
    int sourceId = dragged.getId() << 16 | dragged.getIndex();
    if (inventoryHoldAnchorMouse == null || inventoryHoldAnchorSourceId != sourceId) {
      inventoryHoldAnchorMouse = new Point(mouse.getX(), mouse.getY());
      inventoryHoldAnchorSourceId = sourceId;
      return false;
    }
    int dx = mouse.getX() - inventoryHoldAnchorMouse.getX();
    int dy = mouse.getY() - inventoryHoldAnchorMouse.getY();
    boolean started = (dx * dx + dy * dy) > DRAG_MOVE_THRESHOLD_SQ;
    return started;
  }

  private static boolean hasVisualBankDragStarted(Client client, Widget dragged) {
    if (!isBankMainDragSource(dragged)) {
      return false;
    }
    Point mouse = client.getMouseCanvasPosition();
    if (mouse == null) {
      return false;
    }
    int sourceId = dragged.getId() << 16 | dragged.getIndex();
    if (bankHoldAnchorMouse == null || bankHoldAnchorSourceId != sourceId) {
      bankHoldAnchorMouse = new Point(mouse.getX(), mouse.getY());
      bankHoldAnchorSourceId = sourceId;
      return false;
    }
    int dx = mouse.getX() - bankHoldAnchorMouse.getX();
    int dy = mouse.getY() - bankHoldAnchorMouse.getY();
    boolean started = (dx * dx + dy * dy) > DRAG_MOVE_THRESHOLD_SQ;
    return started;
  }

  private static boolean isBankMainDragSource(Widget dragged) {
    if (isBankDragContainer(dragged)) {
      return true;
    }
    return isBankMainSourceWidget(dragged);
  }

  private static boolean isBankDragContainer(Widget dragged) {
    int id = dragged.getId();
    return id == InterfaceID.Bankmain.ITEMS
        || id == InterfaceID.SharedBank.ITEMS
        || id == InterfaceID.Bankmain.BANKTAGS_DISPLAY_ITEMS;
  }

  @Nullable
  private static Rectangle getWidgetCanvasBounds(Client client, Widget widget) {
    Point location = widget.getCanvasLocation();
    if (location != null && widget.getWidth() > 0 && widget.getHeight() > 0) {
      return new Rectangle(location.getX(), location.getY(), widget.getWidth(), widget.getHeight());
    }

    Rectangle bounds = widget.getBounds();
    if (bounds != null && bounds.width > 0 && bounds.height > 0) {
      return new Rectangle(
          (int) bounds.getX(), (int) bounds.getY(), bounds.width, bounds.height);
    }

    if (TokenItemWidgetScopes.isTokenItemDragWidget(widget)) {
      return null;
    }

    return null;
  }

  @Nullable
  private static SlotType slotFromItemId(ItemManager itemManager, int itemId) {
    return BankItemUtils.resolveSlotType(itemManager, itemId);
  }

  /** Press/dim styling is for left-click hold and drag only, not right-click menus. */
  private static boolean isLeftClickPressHold(Client client) {
    return !client.isMenuOpen() && client.getMouseCurrentButton() == 1;
  }
}

package com.gsl.util;

import net.runelite.api.MenuEntry;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;

public final class TokenItemWidgetScopes {
  private TokenItemWidgetScopes() {}

  public static boolean isTokenItemMenuContext(MenuEntry entry) {
    if (entry == null) {
      return false;
    }
    if (isTokenItemComponent(entry.getParam1())) {
      return true;
    }
    return isTokenItemWidget(entry.getWidget());
  }

  /**
   * Player inventory panel while the bank is open (deposit actions).
   */
  public static boolean isTokenBankDepositContext(MenuEntry entry) {
    int componentId = resolveComponentId(entry);
    return componentId == InterfaceID.Bankside.ITEMS
        || componentId == InterfaceID.SharedBankSide.ITEMS;
  }

  /**
   * Bank item grid (withdraw actions).
   */
  public static boolean isTokenBankWithdrawContext(MenuEntry entry) {
    int componentId = resolveComponentId(entry);
    return componentId == InterfaceID.Bankmain.ITEMS
        || componentId == InterfaceID.Bankmain.BANKTAGS_DISPLAY_ITEMS
        || componentId == InterfaceID.SharedBank.ITEMS
        || componentId == InterfaceID.SharedBank.MAIN_BANK;
  }

  public static boolean isTokenBankActionContext(MenuEntry entry) {
    return isTokenBankDepositContext(entry) || isTokenBankWithdrawContext(entry);
  }

  /**
   * Contexts where token left-click should be overridden (e.g. promote Examine). Bank withdraw/deposit
   * and similar interface actions are excluded so vanilla left-click behavior is preserved.
   */
  public static boolean isTokenLeftClickReorderContext(MenuEntry entry) {
    int componentId = resolveComponentId(entry);
    return componentId == InterfaceID.Inventory.ITEMS;
  }

  private static int resolveComponentId(MenuEntry entry) {
    if (entry.getParam1() > 0) {
      return entry.getParam1();
    }
    Widget widget = entry.getWidget();
    return widget != null ? widget.getId() : -1;
  }

  public static boolean isTokenItemWidget(Widget widget) {
    if (widget == null) {
      return false;
    }
    return isTokenItemInterface(WidgetUtil.componentToInterface(widget.getId()));
  }

  public static boolean isTokenItemInterface(int groupId) {
    return groupId == InterfaceID.INVENTORY
        || groupId == InterfaceID.BANKSIDE
        || groupId == InterfaceID.BANKMAIN
        || groupId == InterfaceID.BANK_DEPOSITBOX
        || groupId == InterfaceID.EQUIPMENT
        || groupId == InterfaceID.EQUIPMENT_SIDE
        || groupId == InterfaceID.WORNITEMS
        || groupId == InterfaceID.SHARED_BANK
        || groupId == InterfaceID.SHARED_BANK_SIDE
        || groupId == InterfaceID.TRADEMAIN
        || groupId == InterfaceID.TRADESIDE;
  }

  public static boolean isTokenItemComponent(int componentId) {
    if (componentId <= 0) {
      return false;
    }
    return componentId == InterfaceID.Inventory.ITEMS
        || componentId == InterfaceID.Bankside.ITEMS
        || componentId == InterfaceID.Bankmain.ITEMS
        || componentId == InterfaceID.Bankmain.BANKTAGS_DISPLAY_ITEMS
        || componentId == InterfaceID.Bankmain.BANKTAGS_DISPLAY_DRAGLAYER
        || componentId == InterfaceID.EquipmentSide.ITEMS
        || componentId == InterfaceID.SharedBank.ITEMS
        || componentId == InterfaceID.SharedBank.MAIN_BANK
        || componentId == InterfaceID.SharedBankSide.ITEMS
        || isTokenItemInterface(WidgetUtil.componentToInterface(componentId));
  }

  public static boolean isTokenItemDragWidget(Widget widget) {
    if (widget == null) {
      return false;
    }
    Widget current = widget;
    while (current != null) {
      if (isTokenItemComponent(current.getId())) {
        return true;
      }
      current = current.getParent();
    }
    return false;
  }
}

